const body = $json.body ?? $json;
const catalogue = {'chips':249,'paprika':229,'chocolate':219,'milk-chocolate':199,'water':89,'juice':189,'soda':149,'apple':159,'banana':139,'bread':349,'croissant':129};
const isInt = v => Number.isSafeInteger(v);
const items = body.order?.items;
let reason = '';
if (body.schemaVersion !== 1 || body.demo !== true || body.event !== 'order.completed') reason = 'Nur Demo-Ereignisse mit Schema 1 erlaubt.';
else if (typeof body.idempotencyKey !== 'string' || !/^[a-zA-Z0-9:-]{1,120}$/.test(body.idempotencyKey)) reason = 'Ungültiger Ereignisschlüssel.';
else if (!/^DEMO-\d{3,6}$/.test(body.order?.id ?? '') || !['manual','customer'].includes(body.order?.source)) reason = 'Ungültige Demo-Bestellung.';
else if (!Array.isArray(items) || items.length < 1 || items.length > 11 || items.some(i => !i || typeof i !== 'object') || new Set(items.map(i => i.productId)).size !== items.length) reason = 'Ungültige Positionen.';
else if (items.some(i => !Object.hasOwn(catalogue,i.productId) || !isInt(i.quantity) || i.quantity < 1 || i.quantity > 100 || i.unitPrice !== catalogue[i.productId])) reason = 'Mengen oder Beispielpreise stimmen nicht.';
else if (!isInt(body.order.totalCents) || body.order.totalCents !== items.reduce((sum,i) => sum + i.quantity * i.unitPrice,0)) reason = 'Gesamtsumme stimmt nicht.';
else if (!Array.isArray(body.lowStockProducts) || body.lowStockProducts.length > 11 || body.lowStockProducts.some(id => !Object.hasOwn(catalogue,id) || !items.some(i => i.productId === id))) reason = 'Ungültige Warnungen.';
else if (!Number.isFinite(Date.parse(body.order.createdAt))) reason = 'Ungültiger Zeitstempel.';
const accepted = !reason;
return [{json:{accepted, demo:true, schemaVersion:1, idempotencyKey:accepted?body.idempotencyKey:'rejected',orderId:accepted?body.order.id:'rejected',totalCents:accepted?body.order.totalCents:0,warningProducts:accepted?body.lowStockProducts:[],description:reason||'Demo-Payload validiert; lokale Buchung bleibt maßgeblich.'}}];
